import{_ as a,o as i,c as t,a2 as n}from"./chunks/framework.Cm6XCzck.js";const u=JSON.parse('{"title":"About Digital Employee Works / 关于数字员工工场","description":"","frontmatter":{},"headers":[],"relativePath":"about.md","filePath":"about.md","lastUpdated":1785829946000}'),o={name:"about.md"};function l(r,e,s,p,c,d){return i(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="about-digital-employee-works-关于数字员工工场" tabindex="-1">About Digital Employee Works / 关于数字员工工场 <a class="header-anchor" href="#about-digital-employee-works-关于数字员工工场" aria-label="Permalink to &quot;About Digital Employee Works / 关于数字员工工场&quot;">​</a></h1><p>Digital Employee Works is maintained by <strong>Zhu Wei / 朱卫 (joinwell52-AI)</strong> as an independent, engineering-driven production project.</p><p>数字员工工场由 <strong>朱卫（joinwell52-AI）</strong> 作为独立、工程驱动的生产项目持续维护。</p><h2 id="current-capability-当前能力" tabindex="-1">Current capability / 当前能力 <a class="header-anchor" href="#current-capability-当前能力" aria-label="Permalink to &quot;Current capability / 当前能力&quot;">​</a></h2><ul><li>Research Report Production Engine V1.3 / 研究报告生产机 V1.3</li><li>Research Runtime Center V4</li><li>Research Runtime Scheduler V2.0</li><li>Research Skills V2.0</li><li>Research Intelligence System V1.0</li></ul><p>The product is a ChatGPT-based Research Analyst Digital Employee with three intelligence pipelines, three permanent research columns, complete-report production at 15:00, release-only Publication at 20:00, and GitHub-verifiable work records.</p><p>该产品是一个通过 ChatGPT 实现的 Research Analyst 数字员工，具备三条研究情报管线、三个长期研究栏目、15:00 完整报告生产、20:00 只负责发版，以及可通过 GitHub 验证的工作记录。</p><h2 id="product-hierarchy-产品层级" tabindex="-1">Product hierarchy / 产品层级 <a class="header-anchor" href="#product-hierarchy-产品层级" aria-label="Permalink to &quot;Product hierarchy / 产品层级&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TMPA + FCoP</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>CodeFlowMu + Digital Employee</span></span></code></pre></div><p>TMPA and FCoP appear in the first row of the website capability section. CodeFlowMu leads the second row, followed by Digital Employee.</p><p>网站能力区中，TMPA 与 FCoP 位于第一排；CodeFlowMu 位于第二排首位，随后是 Digital Employee。</p><h2 id="research-orientation-研究方向" tabindex="-1">Research orientation / 研究方向 <a class="header-anchor" href="#research-orientation-研究方向" aria-label="Permalink to &quot;Research orientation / 研究方向&quot;">​</a></h2><ul><li>Digital Employee positions, workflows, runtime, governance, and evaluation;</li><li>major AI-platform architecture and product evolution;</li><li>open-source agent runtime, protocol, SDK, recovery, evaluation, and observability;</li><li>AI work data and governance;</li><li>formal multi-agent coordination;</li><li>SME-first AI deployment.</li></ul><h2 id="method-方法" tabindex="-1">Method / 方法 <a class="header-anchor" href="#method-方法" aria-label="Permalink to &quot;Method / 方法&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AI Platform + GitHub + Published Research intelligence</span></span>
<span class="line"><span>→ Three-column triage</span></span>
<span class="line"><span>→ Governed research lifecycle</span></span>
<span class="line"><span>→ Complete bilingual Publication Candidate</span></span>
<span class="line"><span>→ GitHub + website release</span></span>
<span class="line"><span>→ Runtime Record + Commit Verify</span></span></code></pre></div><p>Observation Notes record external developments and working judgments. They do not automatically become evidence for the TMPA paper.</p><p>观察笔记记录外部动态与工作判断，但不自动构成 TMPA 论文证据。</p><h2 id="download-下载" tabindex="-1">Download / 下载 <a class="header-anchor" href="#download-下载" aria-label="Permalink to &quot;Download / 下载&quot;">​</a></h2><ul><li><a href="./en/publications/research-report-production-engine-v1.3">Research Report Production Engine V1.3</a></li><li><a href="./zh/publications/research-report-production-engine-v1.3">研究报告生产机 V1.3</a></li><li><a href="https://github.com/joinwell52-AI/joinwell52/archive/refs/heads/main.zip" target="_blank" rel="noreferrer">Download source ZIP / 下载源码 ZIP</a></li></ul>`,19)])])}const b=a(o,[["render",l]]);export{u as __pageData,b as default};
